(()=>{
 if(window.NativePush)return;
 const supported=window.isSecureContext&&'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window;
 let client,workspace,user,device=null,busy=false,registered=null,lastAttempt=0,pending=Promise.resolve(),permissionRequest=null;
 const status=text=>{window.webPushStatus=text;const el=document.querySelector('#web-push-status');if(el)el.textContent=text};
 const base=new URL('./',location.href),swURL=new URL('push-sw.js',base);
 function keyBytes(text){const raw=atob(text.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
 async function registration(){return navigator.serviceWorker.register(swURL.href,{scope:base.pathname})}
 async function registerDevice(ask=false){if(!supported)throw Error('Browser ini belum mendukung Web Push. Gunakan Chrome/Edge atau browser yang mendukung.');if(!user||!client)throw Error('Masuk ke akun terlebih dahulu.');if(busy)return;busy=true;lastAttempt=Date.now();const actor=user,c=client,w=workspace;try{let permission=Notification.permission;if(ask&&permission==='default')permission=await Notification.requestPermission();if(permission!=='granted'){throw Error(permission==='denied'?'Notifikasi diblokir. Izinkan melalui pengaturan situs di browser.':'Tekan Aktifkan untuk mengizinkan notifikasi browser.')}const reg=await registration();if(!reg.active)await new Promise((resolve,reject)=>{const worker=reg.installing||reg.waiting;if(!worker)return reject(Error('Service worker belum aktif. Coba lagi.'));const changed=()=>{if(worker.state==='activated')resolve();if(worker.state==='redundant')reject(Error('Service worker gagal aktif.'))};worker.addEventListener('statechange',changed);changed()});let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:keyBytes(window.UPU_WEB_PUSH_KEY)});if(actor!==user)return;const result=await c.rpc('po_web_push_register',{w,subscription:sub.toJSON()});if(result.error)throw Error(result.error.message);device=result.data;registered=actor;status('Notifikasi browser aktif.');document.querySelector('#web-push-prompt')?.remove();}catch(e){registered=null;status(e.message||'Notifikasi belum terhubung. Coba aktifkan kembali.');throw e}finally{busy=false}}
 function requestOnLogin(){if(!supported)return Promise.resolve('unsupported');if(Notification.permission!=='default')return Promise.resolve(Notification.permission);if(permissionRequest)return permissionRequest;try{permissionRequest=Promise.resolve(Notification.requestPermission()).then(permission=>{if(permission==='granted'&&user&&client)window.WebPush.bind(client,workspace,user);return permission}).catch(()=>{status('Izin notifikasi belum diberikan. Anda tetap dapat masuk.');return 'default'}).finally(()=>{permissionRequest=null});return permissionRequest}catch{status('Izin notifikasi belum diberikan. Anda tetap dapat masuk.');return Promise.resolve('default')}}
 window.WebPush={supported,requestOnLogin,bind(c,w,id){const changed=user!==id;client=c;workspace=w;user=id;if(changed){registered=null;device=null;lastAttempt=0}if(supported&&Notification.permission==='granted'&&registered!==id&&Date.now()-lastAttempt>=30000){pending=registerDevice().catch(()=>{})}},async enable(){pending=registerDevice(true);await pending},async disable(){await pending.catch(()=>{});if(device&&client){const result=await client.rpc('po_push_unregister',{device_token:device});if(result.error)throw Error('Belum dapat melepas notifikasi browser. Periksa koneksi sebelum keluar.')}if(supported){const reg=await navigator.serviceWorker.getRegistration(swURL.href);const sub=await reg?.pushManager.getSubscription();if(sub)await sub.unsubscribe();reg?.active?.postMessage({type:'upu-push-clear'})}user=null;device=null;registered=null;client=null;},prompt(){if(!supported||!user||Notification.permission==='denied'||registered===user||document.querySelector('#web-push-prompt'))return;const host=document.querySelector('#main');if(!host)return;const box=document.createElement('div');box.id='web-push-prompt';box.className='web-push-prompt';box.innerHTML='<span>Terima pemberitahuan PO dan chat melalui browser.</span><button class="btn" onclick="PO.enablePush()">Aktifkan notifikasi browser</button>';host.prepend(box)}};
 if(supported)navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='upu-push-refresh')window.PO?.refresh(true)});
 const params=new URL(location.href).searchParams;if(/^[A-Za-z0-9_-]{1,120}$/.test(params.get('push_chat')||'')){window.pendingPushScreen='chat';window.pendingPushSupplier=params.get('push_chat')}else if(params.get('push_users')==='1')window.pendingPushScreen='users';else if(/^[0-9a-f-]{36}$/i.test(params.get('push_order')||''))window.pendingPushOrder=params.get('push_order');
 if(['push_chat','push_users','push_order'].some(k=>params.has(k))){const clean=new URL(location.href);for(const k of ['push_chat','push_users','push_order'])clean.searchParams.delete(k);history.replaceState(null,'',clean.href)}
})();
